content.text:
{
  "name": "BLE到LSL数据流组件",
  "name_en": "BLE-to-LSL Streamer",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于连接蓝牙低功耗（BLE）设备，订阅其通知数据，将收到的样本整理为数据块并发布到 Lab Streaming Layer（LSL）输出流中，供实验中的实时采集、同步和显示使用。",
  "description_en": "This is a non-physical software component that connects to a Bluetooth Low Energy (BLE) device, subscribes to its notifications, organizes incoming samples into chunks, and publishes them to a Lab Streaming Layer (LSL) outlet for real-time acquisition, synchronization, and visualization in experiments.",
  "actions": [
    {
      "action_name": "auto-start",
      "description": "开始通过 LSL 输出来自 BLE 设备的数据流。",
      "description_en": "Start streaming data from the BLE device to the LSL outlet."
    },
    {
      "action_name": "auto-stop",
      "description": "停止通过 LSL 输出数据流。",
      "description_en": "Stop streaming data to the LSL outlet."
    },
    {
      "action_name": "auto-send_command",
      "description": "向 BLE 设备的发送特征写入命令值。",
      "description_en": "Write a command value to the BLE device's send characteristic."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开 BLE 设备连接并停止适配器。",
      "description_en": "Disconnect from the BLE device and stop the adapter."
    },
    {
      "action_name": "auto-connect",
      "description": "连接 BLE 设备，初始化 LSL 输出，并订阅接收特征通知。",
      "description_en": "Connect to the BLE device, initialize the LSL outlet, and subscribe to notifications on the receive characteristic."
    },
    {
      "action_name": "auto-backend",
      "description": "获取 pygatt 后端名称。",
      "description_en": "get the name of the pygatt backend"
    },
    {
      "action_name": "auto-address",
      "description": "获取设备的 MAC 地址。",
      "description_en": "get the device MAC address"
    },
    {
      "action_name": "auto-subscriptions",
      "description": "获取已配置的 BLE 订阅通道。",
      "description_en": "Get the configured BLE subscription channels."
    },
    {
      "action_name": "auto-make_chunk",
      "description": "生成用于 LSL 输出的数据块。",
      "description_en": "Create a data chunk for LSL output."
    }
  ],
  "tag_hints": [
    "Lab Streaming Layer (LSL)",
    "BLE data streaming",
    "real-time experiment synchronization",
    "Bluetooth Low Energy",
    "pygatt",
    "biosignal data acquisition"
  ]
}

